import { formatShortcut, registerShortcut, shortcuts, type ShortcutOptions } from "@ui-sdk/react/shortcuts"

type ShortcutLayer = ShortcutOptions["layer"]

type ShortcutRegistration = {
  /** Keys like `"u"`, `"mod+k"` or a sequence like `"g i"`. */
  keys: string
  handler: (event: KeyboardEvent) => void
  scope?: string
  layer?: ShortcutLayer
  description?: string
  allowInInput?: boolean
  when?: () => boolean
}

type ListedShortcut = {
  keys: string
  /** Each step formatted for this platform, like `["G", "I"]` or `["⌘K"]`. */
  steps: string[]
  description: string
  scope?: string
  scopeLabel?: string
}

type Entry = { keys: string; last: string[]; description?: string; scope?: string }

const SEQUENCE_TIMEOUT = 1200

const entries = new Set<Entry>()
const scopeCounts = new Map<string, number>()
const scopeLabels = new Map<string, string[]>()
const prefixes = new Map<string, { count: number; off: () => void }>()
let pending: { prefix: string; timer: ReturnType<typeof setTimeout> } | null = null
let listing = false

// UI SDK matches the modifiers it sees, but a symbol or digit takes different ones on different layouts: "?" is
// Shift+/ in the US, Shift+' in Spain, AltGr on some Windows layouts and Option on some Mac ones; "/" is Shift+7 in
// Spain; digits take Shift on AZERTY. So a step that is one such character matches the produced key with whichever
// of Shift, Alt or AltGr (Ctrl+Alt) made it. Letters stay exact, since Shift changes what they mean.
const producedWith = ["", "shift+", "alt+", "alt+shift+", "ctrl+alt+", "ctrl+alt+shift+"]

function variantsOf(step: string) {
  return /^[^\p{L}\s+]$/u.test(step) ? producedWith.map((modifiers) => `${modifiers}${step}`) : [step]
}

function stepsOf(keys: string) {
  return keys.trim().split(/\s+/)
}

function isTypingTarget(element: Element | null) {
  if (!(element instanceof HTMLElement)) return false
  if (element.isContentEditable) return true
  const editable = element.closest("[contenteditable]")
  return editable !== null && editable.getAttribute("contenteditable") !== "false"
}

function clearPending() {
  if (!pending) return
  clearTimeout(pending.timer)
  pending = null
}

// The next key press ends the sequence either way; clearing waits until UI SDK has matched it.
function startPending(prefix: string) {
  clearPending()
  pending = { prefix, timer: setTimeout(clearPending, SEQUENCE_TIMEOUT) }
  const onNext = (event: KeyboardEvent) => {
    if (["Shift", "Control", "Alt", "Meta"].includes(event.key)) return
    document.removeEventListener("keydown", onNext, true)
    setTimeout(clearPending, 0)
  }
  document.addEventListener("keydown", onNext, true)
}

function retainPrefix(prefix: string) {
  const existing = prefixes.get(prefix)
  if (existing) {
    existing.count += 1
  } else {
    const offs = variantsOf(prefix).map((keys) =>
      registerShortcut(keys, () => startPending(prefix), {
        when: () => pending === null && !isTypingTarget(document.activeElement),
      }),
    )
    const off = () => {
      for (const unregister of offs) unregister()
    }
    prefixes.set(prefix, { count: 1, off })
  }
  return () => {
    const current = prefixes.get(prefix)
    if (!current) return
    current.count -= 1
    if (current.count > 0) return
    current.off()
    prefixes.delete(prefix)
  }
}

/** Registers a shortcut or a two-step sequence (`"g i"`) in UI SDK's shared shortcuts. Returns the cleanup. */
function addShortcut(registration: ShortcutRegistration) {
  const steps = stepsOf(registration.keys)
  const [first, second] = steps
  if (!first || steps.length > 2) throw new RangeError(`Shortcut "${registration.keys}" needs one or two steps.`)
  const userWhen = registration.when ?? (() => true)
  const typingOk = () => registration.allowInInput === true || !isTypingTarget(document.activeElement)
  const entry: Entry = {
    keys: registration.keys,
    last: variantsOf(second ?? first),
    description: registration.description,
    scope: registration.scope,
  }
  const options = { scope: registration.scope, layer: registration.layer, allowInInput: registration.allowInInput }
  const description = registration.description
  const offs =
    second === undefined
      ? entry.last.map((keys) =>
          registerShortcut(keys, registration.handler, {
            ...options,
            description,
            when: () => (listing || pending === null) && typingOk() && userWhen(),
          }),
        )
      : [
          retainPrefix(first),
          ...entry.last.map((keys) =>
            registerShortcut(
              keys,
              (event) => {
                clearPending()
                registration.handler(event)
              },
              {
                ...options,
                description,
                when: () => (listing || pending?.prefix === first) && typingOk() && userWhen(),
              },
            ),
          ),
        ]
  entries.add(entry)
  return () => {
    entries.delete(entry)
    for (const off of offs) off()
  }
}

function setScopeActive(name: string, active: boolean) {
  const count = Math.max(0, (scopeCounts.get(name) ?? 0) + (active ? 1 : -1))
  scopeCounts.set(name, count)
  shortcuts.setScope(name, count > 0)
}

function addScopeLabel(name: string, label: string) {
  const labels = scopeLabels.get(name) ?? []
  labels.push(label)
  scopeLabels.set(name, labels)
  return () => {
    const index = labels.indexOf(label)
    if (index !== -1) labels.splice(index, 1)
  }
}

function formatSteps(keys: string) {
  return stepsOf(keys).map((step) => formatShortcut(step))
}

/**
 * The shortcuts that can run now, with a description, in registration order. A modal pauses the page's
 * shortcuts, so a help dialog reads this before it opens.
 */
function listShortcuts(): ListedShortcut[] {
  listing = true
  let available: ReturnType<typeof shortcuts.list>
  try {
    available = shortcuts.list()
  } finally {
    listing = false
  }
  const known = [...entries]
  const claimed = new Set<Entry>()
  const result: ListedShortcut[] = []
  for (const info of available) {
    if (!info.description) continue
    const entry = known.find(
      (candidate) =>
        candidate.last.includes(info.keys) &&
        candidate.description === info.description &&
        candidate.scope === info.scope &&
        !claimed.has(candidate),
    )
    if (entry) claimed.add(entry)
    else if (known.some((candidate) => claimed.has(candidate) && candidate.last.includes(info.keys))) continue
    const keys = entry?.keys ?? info.keys
    result.push({
      keys,
      steps: entry ? formatSteps(keys) : [info.hint],
      description: info.description,
      scope: info.scope,
      scopeLabel: info.scope === undefined ? undefined : scopeLabels.get(info.scope)?.at(-1),
    })
  }
  return result
}

export { addScopeLabel, addShortcut, formatSteps, isTypingTarget, listShortcuts, setScopeActive, stepsOf }
export type { ListedShortcut, ShortcutLayer, ShortcutRegistration }

"use client"

import { renderElement, type PartProps } from "@ui-sdk/react/primitive"
import { useShortcutHint } from "@ui-sdk/react/shortcuts"
import { useCallback, useMemo, useState, type FocusEvent, type Ref } from "react"

import { Kbd, KbdGroup } from "@/components/ui/kbd"
import {
  addScopeLabel,
  formatSteps,
  listShortcuts,
  setScopeActive,
  stepsOf,
  type ListedShortcut,
} from "@/components/ui/shortcuts-registry"
import {
  ScopeContext,
  useShortcut,
  type ScopeContextValue,
  type UseShortcutOptions,
} from "@/components/ui/use-shortcut"
import { cn } from "@/lib/utils"

type ShortcutScopeProps = PartProps<"div"> & {
  /** The scope's name. Shortcuts registered inside it run only while it is active. */
  name: string
  /** How `ShortcutsDialog` titles this scope's group. */
  label?: string
  /**
   * `"focus"` (default): active while focus is inside, like an editor or a list. `true`: while mounted, like an
   * open side panel. `false`: never.
   */
  active?: boolean | "focus"
}

function assignRef<T>(ref: Ref<T> | undefined, value: T | null) {
  if (typeof ref === "function") return ref(value)
  if (ref) ref.current = value
}

const focusedScopes = new WeakSet<Element>()

function enterScope(element: Element, name: string) {
  if (focusedScopes.has(element)) return
  focusedScopes.add(element)
  setScopeActive(name, true)
}

function leaveScope(element: Element, name: string) {
  if (!focusedScopes.delete(element)) return
  setScopeActive(name, false)
}

/** Limits the shortcuts registered inside it to a region, or to an open panel or dialog. */
function ShortcutScope({ name, label, active = "focus", render, onFocus, onBlur, ref, ...props }: ShortcutScopeProps) {
  const [element, setElement] = useState<HTMLDivElement | null>(null)
  const context = useMemo<ScopeContextValue>(() => ({ scope: name, layer: () => element }), [name, element])

  const scopeRef = useCallback(
    (node: HTMLDivElement | null) => {
      const cleanup = assignRef(ref, node)
      setElement(node)
      if (!node) return
      const offLabel = label === undefined ? undefined : addScopeLabel(name, label)
      if (active === true) setScopeActive(name, true)
      return () => {
        offLabel?.()
        if (active === true) setScopeActive(name, false)
        leaveScope(node, name)
        if (typeof cleanup === "function") cleanup()
        else assignRef(ref, null)
      }
    },
    [name, label, active, ref],
  )

  const handlers = {
    onFocus: (event: FocusEvent<HTMLDivElement>) => {
      onFocus?.(event)
      if (active === "focus") enterScope(event.currentTarget, name)
    },
    onBlur: (event: FocusEvent<HTMLDivElement>) => {
      onBlur?.(event)
      if (!event.currentTarget.contains(event.relatedTarget)) leaveScope(event.currentTarget, name)
    },
  }

  return (
    <ScopeContext value={context}>
      {renderElement(
        "div",
        { ...props, ...handlers, ref: scopeRef, "data-slot": "shortcut-scope", "data-scope": name },
        render,
      )}
    </ScopeContext>
  )
}

function ShortcutKey({ step }: { step: string }) {
  return <Kbd>{useShortcutHint(step).text}</Kbd>
}

type ShortcutHintProps = Omit<PartProps<"kbd">, "children"> & {
  /** Keys like `"u"`, `"mod+k"` or `"g i"`. */
  keys: string
}

/** The keys as `Kbd`s, formatted for this platform. Decorative: give the control `aria-keyshortcuts` instead. */
function ShortcutHint({ keys, className, ...props }: ShortcutHintProps) {
  return (
    <KbdGroup aria-hidden="true" data-slot="shortcut-hint" className={cn("shrink-0", className)} {...props}>
      {stepsOf(keys).map((step, index) => (
        <ShortcutKey key={`${String(index)}-${step}`} step={step} />
      ))}
    </KbdGroup>
  )
}

/** `aria-keyshortcuts` for one step; a sequence has no ARIA form, so it gets none. */
function useAriaKeyshortcuts(keys: string | undefined) {
  const single = keys !== undefined && stepsOf(keys).length === 1
  // The hook needs keys on every render; a placeholder stands in when there are none to describe.
  const hint = useShortcutHint(single ? keys : "a")
  return single ? hint.ariaKeyshortcuts : undefined
}

export { ariaKeyshortcuts, formatShortcut, shortcuts, useShortcutHint } from "@ui-sdk/react/shortcuts"
/** Each step of `keys` formatted for this platform, like `["G", "I"]`; for rows of your own in a help screen. */
const formatShortcutSteps = formatSteps

export { formatShortcutSteps, listShortcuts, ShortcutHint, ShortcutScope, useAriaKeyshortcuts, useShortcut }
export type { ListedShortcut, ShortcutHintProps, ShortcutScopeProps, UseShortcutOptions }

"use client"

import { createContext, use, useEffect, useLayoutEffect, useRef, type RefObject } from "react"

import { addShortcut, type ShortcutLayer } from "@/components/ui/shortcuts-registry"

type ScopeContextValue = { scope: string; layer: () => Element | null }

const ScopeContext = createContext<ScopeContextValue | null>(null)

type UseShortcutOptions = {
  /** A named scope; inside a `ShortcutScope` it defaults to that scope's name. `null` makes it global. */
  scope?: string | null
  /** `false` leaves it unregistered. */
  enabled?: boolean
  /** What it does, for the `ShortcutsDialog`. Without one it still runs but isn't listed. */
  description?: string
  /** Whether it runs while focus is in a text field or contenteditable. Shortcuts with ⌘, Ctrl or ⌥ always do. */
  allowInInput?: boolean
  /** Checked on every key press. */
  when?: () => boolean
  /** An element inside a popup, or a ref to one: the shortcut runs only while that popup is open. */
  layer?: ShortcutLayer | RefObject<Element | null>
}

function layerOf(layer: UseShortcutOptions["layer"], scope: ScopeContextValue | null): ShortcutLayer {
  if (layer === undefined) return scope ? scope.layer : undefined
  if (layer instanceof Element || typeof layer === "function") return layer
  return () => layer.current
}

/**
 * Registers a shortcut while the component is mounted: `"u"`, `"mod+k"`, `"?"` or a sequence `"g i"`. Plain keys
 * never fire while someone types in a field or contenteditable, nor during IME composition. Built on UI SDK's
 * shared `shortcuts`, so modals pause page shortcuts and `ShortcutsDialog` lists them.
 */
function useShortcut(
  keys: string | null | undefined,
  handler: (event: KeyboardEvent) => void,
  { scope, enabled = true, description, allowInInput, when, layer }: UseShortcutOptions = {},
) {
  const context = use(ScopeContext)
  const resolvedScope = scope === null ? undefined : (scope ?? context?.scope)
  const layerContext = scope === null ? null : context
  const hasLayer = layer !== undefined || layerContext !== null
  const latest = useRef({ handler, when, layer, layerContext })
  // oxlint-disable-next-line p-otero/no-latest-ref-effect -- ShortcutsDialog lists shortcuts in the render that opens it (the modal pauses them after), which calls `when` and the layer; an effect event throws during render
  useLayoutEffect(() => {
    latest.current = { handler, when, layer, layerContext }
  })

  useEffect(() => {
    if (!keys || !enabled) return
    const currentLayer = () => {
      const resolved = layerOf(latest.current.layer, latest.current.layerContext)
      return typeof resolved === "function" ? (resolved() ?? null) : (resolved ?? null)
    }
    return addShortcut({
      keys,
      handler: (event) => latest.current.handler(event),
      scope: resolvedScope,
      layer: hasLayer ? currentLayer : undefined,
      description,
      allowInInput,
      when: () => latest.current.when?.() ?? true,
    })
  }, [keys, enabled, resolvedScope, hasLayer, description, allowInInput])
}

export { ScopeContext, useShortcut }
export type { ScopeContextValue, UseShortcutOptions }
